```cpp
void Aggregator::run() {
  bool any_new = false;
  for(const auto& w : workers) { ... worker->work(workers) ... }   // non-process workers
  for(const auto& w : workers) { ... worker->work(workers) ... }   // process workers
  for(const auto& r : handlers) {
    auto handler = r.second;
    if(handler && (any_new || handler->get_status() == Handler::e_handler_processing)) {
      handler->try_handle_work(workers);
    }
  }
