// instead of a single delay(100) + give-up.
static bool wait_for_connection(uint32_t timeout_ms) {
  uint32_t start = millis();
  while (millis() - start < timeout_ms) {
    if (WiFi.status() == WL_CONNECTED) {
      return true;
    }
    delay(100);
  }
  return WiFi.status() == WL_CONNECTED;
}

