#include "api_connector.h"
#include "identifiers.h"

#define RETRY_TIMEOUT 10000

// subtracting 1 seconds so data is sent more often than not.
#define SEND_FREQUENCY(last_send, sec) ((last_send) == 0 || (millis() - (last_send)) > (((sec) * 1000) - 500))

ApiConnector::ApiConnector(LocalStorage& config) : Handler(), _http_client(), _config(config), _payload(""), _post_count(0), _last_post(0), _last_retry(0) {
}

bool ApiConnector::time_to_send(bool in_fixed_range, bool alert) const {
  if (in_fixed_range) {
    return SEND_FREQUENCY(_last_post, alert ? API_SEND_SECONDS_DELAY_ALERT : API_SEND_SECONDS_DELAY);
  }
  return SEND_FREQUENCY(_last_post, API_SEND_SECONDS_DELAY_ROAMING);
}

bool ApiConnector::activate(bool retry) {
  if (WiFiWrapper_i.wifi_connected()) {
    return true;
  }
  if (retry && millis() - _last_retry < RETRY_TIMEOUT) {
    return false;
  }
  _last_retry = millis();

  WiFiWrapper_i.connect_wifi(_config.get_active_wifi_ssid(), _config.get_active_wifi_password(), !retry);

  return WiFi.isConnected();
}

void ApiConnector::maintain_connection() {
  if (!_config.get_fixed_device_id()) {
    // No valid device id configured, nothing to upload, leave wifi alone
    return;
  }
  if (WiFiWrapper_i.ap_server_up()) {
    // User is on the AP config screen, don't fight it
    return;
  }
  if (WiFiWrapper_i.consume_disconnect_event()) {
    // A disconnect event fired: skip the backoff and retry now
    M5_LOGD("WiFi connector: disconnect event detected, retrying now");
    _last_retry = 0;
  }
  activate(true);
}

void ApiConnector::deactivate() {

#ifndef BGEIGIEZEN_APICONNECTOR_H_
#define BGEIGIEZEN_APICONNECTOR_H_

#include <WiFi.h>
#include <HTTPClient.h>

#include <Handler.hpp>

#include "workers/local_storage.h"
#include "user_config.h"
#include "utils/wifi_connection.h"
#include "workers/log_aggregator.h"

/**
 * Connects over WiFi to the API to send readings
 */
class ApiConnector : public Handler {
 public:
  /**
   * Collection of statuses for the api data handling, default is idle.
   */
  enum ApiHandlerStatus {
    e_api_reporter_send_success,
    e_api_reporter_error_to_json,
    e_api_reporter_error_not_connected,
    e_api_reporter_error_remote_not_available,
    e_api_reporter_error_server_rejected_post_400,
    e_api_reporter_error_server_rejected_post_401,
    e_api_reporter_error_server_rejected_post_403,
    e_api_reporter_error_server_rejected_post_5xx,
  };

  explicit ApiConnector(LocalStorage& config);
  virtual ~ApiConnector() = default;

  uint32_t get_post_count() const;

  /**
   * Called every loop iteration (independent of sensor data freshness) to
   * keep the WiFi link alive: reacts to disconnect events immediately and
   * otherwise retries on the normal backoff.
   */
  void maintain_connection();

 protected:

  /**
   * Check if enough time has passed to send the latest reading to api
   * @param in_fixed_range: If within configured range, a different send frequency is used
   * @param alert: If alerted, a different send frequency is used
   * @return true if time to send
   */
  bool time_to_send(bool in_fixed_range, bool alert) const;

  /**
   * Initialize the connection
   * @param initial: set to false if its for reconnect / connect in error
   * @return true if connection with the wifi was made
   */
  bool activate(bool retry) override;

  /**
   * Stop the connection
   */
  void deactivate() override;

  int8_t handle_produced_work(const worker_map_t& workers) override;

  bool reading_to_json(const DataLine& reading, char* out);

  int8_t handle_async() override;

 private:

  HTTPClient _http_client;
  LocalStorage& _config;
  char _payload[200];
  uint32_t _post_count;
  uint32_t _last_post;
  uint32_t _last_retry;
};

#endif //BGEIGIEZEN_APICONNECTOR_H_

